import path from 'path';
import { build } from 'vite';
import { OUTPUT_DIR, ROLLUP_OPTIONS } from './constants.js';
import codeBlockingPlugin from './plugins/codeBlockingPlugin.js';
import codeCheckingPlugin from './plugins/codeCheckingPlugin.js';
import cssBlockingPlugin from './plugins/cssBlockingPlugin.js';
import friendlyLoggingPlugin from './plugins/friendlyLoggingPlugin.js';
import manifestPlugin from './plugins/manifestPlugin.js';
import securityAuditPlugin from './plugins/securityAuditPlugin.js';
import { getUrlSafeFileName, warnAboutIgnoredConfigFiles } from './utils.js';
export { runNpmAuditJson, MAX_NPM_AUDIT_JSON_BUFFER, } from './npmSecurityAudit.js';
// This build config prevents vite and postcss from discovering config in customer-controlled source.
// It's shared across all build paths to ensure consistent behavior.
export const ISOLATED_BUILD_CONFIG = {
    configFile: false,
    envFile: false,
    envPrefix: ['__UIE_NO_ENV__'],
    css: { postcss: {} },
};
const allowedExtensions = ['.js', '.ts', '.tsx', '.jsx'];
export const extensionErrorBaseMessage = `Supported file extensions are [${allowedExtensions.join(', ')}], received:`;
export async function buildSingleExtension({ file, outputDir = OUTPUT_DIR, emptyOutDir = true, minify = false, root = process.cwd(), // This is the vite default, so using that as our default
logLevel = 'info', appConfig, codeCheckingPluginEnabled = false, securityAuditPluginEnabled = false, }) {
    const output = getUrlSafeFileName(file);
    warnAboutIgnoredConfigFiles(root);
    // Collect any CSS-blocked imports; we throw after build() so the error reaches the
    // caller with a clean message rather than Vite's internal [plugin-name] prefix.
    const cssBlockingErrors = [];
    await build({
        logLevel,
        root,
        ...ISOLATED_BUILD_CONFIG,
        // cssBlockingPlugin must be at the top level so enforce: 'pre' is respected;
        // rollupOptions.plugins are appended after Vite's own plugins and never see resolveId
        // for files that vite:resolve already handles.
        plugins: [
            cssBlockingPlugin({
                onCssBlocked: (msg) => {
                    cssBlockingErrors.push(msg);
                },
            }),
        ],
        define: {
            'process.env.NODE_ENV': JSON.stringify(process.env.NODE_ENV || 'production'),
        },
        build: {
            lib: {
                entry: file,
                name: output,
                formats: ['iife'],
                fileName: () => output,
            },
            rollupOptions: {
                ...ROLLUP_OPTIONS,
                plugins: [
                    manifestPlugin({
                        output,
                        extensionPath: root,
                        logger: console,
                        manifestConfig: appConfig,
                    }),
                    friendlyLoggingPlugin({ logger: console }),
                    codeBlockingPlugin({ logger: console, extensionPath: root }),
                    codeCheckingPluginEnabled &&
                        codeCheckingPlugin({
                            logger: console,
                        }),
                    securityAuditPluginEnabled &&
                        securityAuditPlugin({
                            logger: console,
                            auditRoot: root,
                            extensionLabel: output,
                        }),
                ],
            },
            outDir: outputDir,
            emptyOutDir,
            minify,
        },
    });
    if (cssBlockingErrors.length > 0) {
        throw new Error(cssBlockingErrors.join('\n'));
    }
}
export async function remoteBuild(args) {
    const { root, entryPoint, outputDir = OUTPUT_DIR, logLevel, appConfig, } = args;
    if (!root) {
        console.error('remoteBuild Error: root is required');
        return;
    }
    if (!entryPoint) {
        console.error('remoteBuild Error: entryPoint is required');
        return;
    }
    const fileInfo = path.parse(entryPoint);
    if (!allowedExtensions.includes(fileInfo.ext)) {
        throw new Error(`${extensionErrorBaseMessage} ${fileInfo.ext}`);
    }
    await buildSingleExtension({
        file: entryPoint,
        outputDir,
        minify: true,
        root,
        logLevel,
        appConfig,
        codeCheckingPluginEnabled: false,
        securityAuditPluginEnabled: false,
    });
}
